      "excerpt": "// src-tauri/src/commands/chat.rs
use serde::{Deserialize, Serialize};
use tauri::ipc::Channel;
use tauri::State;
use crate::AppState;

#[derive(Debug, Clone, Deserialize)]
pub struct ChatMessage {
    pub role:    String,
    pub content: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ChatRequest {
    pub model:    String,
    pub messages: Vec<ChatMessage>,
    pub channel:  Channel<StreamEvent>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case")]
pub enum StreamEvent {
    TextDelta  { text:   String },
    Thinking   { text:   String },
    ToolCall   { name:   String, input:  serde_json::Value },
    ToolResult { name:   String, output: serde_json::Value },
    Finish     { reason: String },
}

#[derive(Debug, Clone, Serialize)]
pub struct StreamHandle { pub session_id: String }

#[tauri::command]
pub async fn stream_chat(request: ChatRequest, state: State<'_, AppState>) -> Result<StreamHandle, String> {
    let id = uuid::Uuid::new_v4().to_string();
    let prompt = request.messages.last().map(|m| m.content.clone()).unwrap_or_default();
    let ch = request.channel;

    let inf = state.inference.clone();
    tauri::async_runtime::spawn(async move {
        let _ = inf.complete(&request.model, &prompt, Box::new(move |text| {
            let _ = ch.send(StreamEvent::TextDelta { text });
        })).await;
    });

    Ok(StreamHandle { session_id: id })
}

#[tauri::command]
pub async fn cancel_session(_session_id: String) -> Result<(), String> { Ok(()) }

#[tauri::command]
pub async fn get_active_sessions() -> Result<Vec<String>, String> { Ok(vec![]) }
"
    }
